80	// ─────────────────────────────────────────────────────────────────────────────
81	// TimestampParsePlugin
82	// ─────────────────────────────────────────────────────────────────────────────
83	
84	/// Parse a timestamp string into ISO 8601 format.
85	///
86	/// Supported input formats (tried in order):
87	/// 1. Unix epoch seconds (integer or float string)
88	/// 2. User-provided format strings (passed verbatim to `chrono`)
89	/// 3. Common formats: `%Y-%m-%dT%H:%M:%S%.f%z`, `%Y-%m-%d %H:%M:%S`,
90	///    `%d/%b/%Y:%H:%M:%S %z` (Apache/nginx), RFC 2822, RFC 3339
91	pub struct TimestampParsePlugin {
92	    /// Source field containing the raw timestamp string.
93	    field: String,
94	    /// Extra format strings (chrono strftime syntax).
95	    formats: Vec<String>,
96	    /// Destination field (defaults to `@timestamp` when `None`).
97	    target: Option<String>,
98	}
99	
100	impl TimestampParsePlugin {
101	    pub fn new(field: impl Into<String>, formats: Vec<String>, target: Option<String>) -> Self {
102	        Self {
103	            field: field.into(),
104	            formats,
105	            target,
106	        }
107	    }
108	
109	    fn target_field(&self) -> &str {
110	        self.target.as_deref().unwrap_or("@timestamp")
111	    }
112	}
113	
114	impl TransformPlugin for TimestampParsePlugin {
115	    fn name(&self) -> &str {
116	        "timestamp_parse"
117	    }
118	
119	    fn process(&self, doc: &mut Value) -> ProcessAction {
120	        let raw = match doc.get(&self.field) {
121	            Some(Value::String(s)) => s.clone(),
122	            Some(Value::Number(n)) => n.to_string(),
123	            _ => return ProcessAction::Pass,
124	        };
125	
126	        // Try unix epoch (integer seconds).
127	        if let Ok(epoch) = raw.trim().parse::<i64>() {
128	            use chrono::{TimeZone, Utc};
129	            let dt = Utc.timestamp_opt(epoch, 0).single();
130	            if let Some(dt) = dt {
131	                let iso = dt.to_rfc3339();
132	                doc[self.target_field()] = Value::String(iso);
133	                return ProcessAction::Pass;
134	            }
135	        }
136	
137	        // Try unix epoch float.
138	        if let Ok(epoch_f) = raw.trim().parse::<f64>() {
139	            use chrono::{TimeZone, Utc};
140	            let secs = epoch_f as i64;
141	            let nanos = ((epoch_f.fract()) * 1_000_000_000.0) as u32;
142	            let dt = Utc.timestamp_opt(secs, nanos).single();
143	            if let Some(dt) = dt {
144	                let iso = dt.to_rfc3339();
145	                doc[self.target_field()] = Value::String(iso);
146	                return ProcessAction::Pass;
147	            }
148	        }
149	
150	        // Try user-supplied formats.
151	        for fmt in &self.formats {
152	            if let Ok(dt) = chrono::NaiveDateTime::parse_from_str(&raw, fmt) {
153	                use chrono::TimeZone;
154	                let utc = chrono::Utc.from_utc_datetime(&dt);
155	                doc[self.target_field()] = Value::String(utc.to_rfc3339());
156	                return ProcessAction::Pass;
157	            }
158	        }
159	
160	        // Try RFC 3339 / ISO 8601 (chrono's built-in parser).
161	        if let Ok(dt) = chrono::DateTime::parse_from_rfc3339(&raw) {
162	            doc[self.target_field()] = Value::String(dt.to_rfc3339());
163	            return ProcessAction::Pass;
164	        }
165	
166	        // Try RFC 2822.
167	        if let Ok(dt) = chrono::DateTime::parse_from_rfc2822(&raw) {
168	            doc[self.target_field()] = Value::String(dt.to_rfc3339());
169	            return ProcessAction::Pass;
170	        }
171	
172	        // Try Apache/nginx combined log format: "10/Apr/2026:12:00:00 +0000"
173	        if let Ok(dt) = chrono::DateTime::parse_from_str(&raw, "%d/%b/%Y:%H:%M:%S %z") {
174	            doc[self.target_field()] = Value::String(dt.to_rfc3339());
175	            return ProcessAction::Pass;
176	        }
177	
178	        // Try "YYYY-MM-DD HH:MM:SS"
179	        if let Ok(dt) = chrono::NaiveDateTime::parse_from_str(&raw, "%Y-%m-%d %H:%M:%S") {
180	            use chrono::TimeZone;
181	            let utc = chrono::Utc.from_utc_datetime(&dt);
182	            doc[self.target_field()] = Value::String(utc.to_rfc3339());
183	            return ProcessAction::Pass;
184	        }
185	
186	        debug!(
187	            field = self.field.as_str(),
188	            raw = raw.as_str(),
189	            "timestamp_parse: no format matched"
190	        );
191	        ProcessAction::Pass
192	    }
193	}
