195	// ─────────────────────────────────────────────────────────────────────────────
196	// FieldRenamePlugin
197	// ─────────────────────────────────────────────────────────────────────────────
198	
199	/// Rename document fields.
200	///
201	/// `mappings` maps `old_name → new_name`.  Fields not present in the document
202	/// are silently skipped.
203	pub struct FieldRenamePlugin {
204	    mappings: HashMap<String, String>,
205	}
206	
207	impl FieldRenamePlugin {
208	    pub fn new(mappings: HashMap<String, String>) -> Self {
209	        Self { mappings }
210	    }
211	}
212	
213	impl TransformPlugin for FieldRenamePlugin {
214	    fn name(&self) -> &str {
215	        "field_rename"
216	    }
217	
218	    fn process(&self, doc: &mut Value) -> ProcessAction {
219	        if let Some(obj) = doc.as_object_mut() {
220	            for (old, new) in &self.mappings {
221	                if let Some(val) = obj.remove(old.as_str()) {
222	                    obj.insert(new.clone(), val);
223	                }
224	            }
225	        }
226	        ProcessAction::Pass
227	    }
228	}
