231	// DropFieldPlugin
232	// ─────────────────────────────────────────────────────────────────────────────
233	
234	/// Remove one or more fields from a document.
235	pub struct DropFieldPlugin {
236	    fields: Vec<String>,
237	}
238	
239	impl DropFieldPlugin {
240	    pub fn new(fields: Vec<String>) -> Self {
241	        Self { fields }
242	    }
243	}
244	
245	impl TransformPlugin for DropFieldPlugin {
246	    fn name(&self) -> &str {
247	        "drop_field"
248	    }
249	
250	    fn process(&self, doc: &mut Value) -> ProcessAction {
251	        if let Some(obj) = doc.as_object_mut() {
252	            for field in &self.fields {
253	                obj.remove(field.as_str());
254	            }
255	        }
256	        ProcessAction::Pass
257	    }
258	}
