290	// ─────────────────────────────────────────────────────────────────────────────
291	// RoutePlugin
292	// ─────────────────────────────────────────────────────────────────────────────
293	
294	/// Route a document to a different target index based on a field value.
295	///
296	/// Looks up `doc[field]` in the `routes` map.  If a match is found, returns
297	/// [`ProcessAction::Route`] with the target index name.  Falls back to the
298	/// `default` index if configured; otherwise returns [`ProcessAction::Pass`].
299	pub struct RoutePlugin {
300	    /// Field to inspect.
301	    field: String,
302	    /// Field value → target index name.
303	    routes: HashMap<String, String>,
304	    /// Fallback target (used when no route matches).
305	    default: Option<String>,
306	}
307	
308	impl RoutePlugin {
309	    pub fn new(
310	        field: impl Into<String>,
311	        routes: HashMap<String, String>,
312	        default: Option<String>,
313	    ) -> Self {
314	        Self {
315	            field: field.into(),
316	            routes,
317	            default,
318	        }
319	    }
320	}
321	
322	impl TransformPlugin for RoutePlugin {
323	    fn name(&self) -> &str {
324	        "route"
325	    }
326	
327	    fn process(&self, doc: &mut Value) -> ProcessAction {
328	        let key = match doc.get(&self.field).and_then(Value::as_str) {
329	            Some(v) => v.to_owned(),
330	            None => {
331	                return self
332	                    .default
333	                    .as_ref()
334	                    .map(|d| ProcessAction::Route(d.clone()))
335	                    .unwrap_or(ProcessAction::Pass);
336	            }
337	        };
338	
339	        if let Some(target) = self.routes.get(&key) {
340	            ProcessAction::Route(target.clone())
341	        } else if let Some(default) = &self.default {
342	            ProcessAction::Route(default.clone())
343	        } else {
344	            ProcessAction::Pass
345	        }
346	    }
347	}
