349	// ─────────────────────────────────────────────────────────────────────────────
350	// GrokPlugin
351	// ─────────────────────────────────────────────────────────────────────────────
352	
353	/// Parse unstructured log text using Grok-style named patterns.
354	///
355	/// Supported pattern names:
356	/// - `NGINX_COMBINED` — standard nginx combined log format
357	/// - `APACHE_COMBINED` — Apache httpd combined log format
358	/// - `SYSLOG` — RFC 3164 syslog line
359	/// - `POSTGRESQL` — PostgreSQL log line
360	///
361	/// Extracted fields are merged into the root document.
362	pub struct GrokPlugin {
363	    /// Field containing the raw log line.
364	    field: String,
365	    /// Grok pattern name (e.g. `"NGINX_COMBINED"`).
366	    pattern_name: String,
367	    /// Compiled regex derived from the pattern.
368	    regex: Regex,
369	    /// Named capture group names in the order they appear in the regex.
370	    capture_names: Vec<Option<String>>,
371	}
372	
373	impl GrokPlugin {
374	    pub fn new(field: impl Into<String>, pattern_name: impl Into<String>) -> Self {
375	        let pattern_name = pattern_name.into();
376	        let (regex_str, _) = grok_pattern(&pattern_name);
377	        let regex = Regex::new(regex_str).expect("built-in grok pattern must compile");
378	        let capture_names: Vec<Option<String>> = regex
379	            .capture_names()
380	            .map(|n| n.map(str::to_string))
381	            .collect();
382	
383	        Self {
384	            field: field.into(),
385	            pattern_name,
386	            regex,
387	            capture_names,
388	        }
389	    }
390	}
391	
392	impl TransformPlugin for GrokPlugin {
393	    fn name(&self) -> &str {
394	        "grok"
395	    }
396	
397	    fn process(&self, doc: &mut Value) -> ProcessAction {
398	        let text = match doc.get(&self.field).and_then(Value::as_str) {
399	            Some(s) => s.to_owned(),
400	            None => return ProcessAction::Pass,
401	        };
402	
403	        if let Some(caps) = self.regex.captures(&text) {
404	            if let Some(obj) = doc.as_object_mut() {
405	                for name in self.capture_names.iter().flatten() {
406	                    if let Some(m) = caps.name(name) {
407	                        obj.insert(name.clone(), Value::String(m.as_str().to_string()));
408	                    }
409	                }
410	            }
411	        } else {
412	            debug!(
413	                field = self.field.as_str(),
414	                pattern = self.pattern_name.as_str(),
415	                "grok: pattern did not match"
416	            );
417	        }
418	
419	        ProcessAction::Pass
420	    }
421	}
422	
423	/// Built-in grok pattern names accepted by the `grok` stage.
424	///
425	/// `GENERIC` is the explicit opt-in for the catch-everything-as-`message`
426	/// pattern. It used to be reachable by *typo*: `grok_pattern` fell through to
427	/// it for any unrecognised name, so `"pattern": "NGINX_COMBINE"` compiled
428	/// happily and then extracted exactly one field (`message`) out of every
429	/// access log line — an accepted-and-ignored configuration (issue #204).
430	/// `build_plugin` now rejects names outside this list, so the generic pattern
431	/// is only ever used when it was actually asked for.
432	pub const GROK_PATTERN_NAMES: &[&str] = &[
433	    "NGINX_COMBINED",
434	    "APACHE_COMBINED",
435	    "SYSLOG",
436	    "POSTGRESQL",
437	    "GENERIC",
438	];
439	
440	/// Returns `(regex_str, field_names)` for a built-in grok pattern.
441	fn grok_pattern(name: &str) -> (&'static str, &'static [&'static str]) {
442	    match name {
443	        "NGINX_COMBINED" | "APACHE_COMBINED" => (
444	            r#"^(?P<remote_addr>\S+) - (?P<remote_user>\S+) \[(?P<time_local>[^\]]+)\] "(?P<method>\S+) (?P<request_uri>\S+) (?P<http_version>[^"]+)" (?P<status>\d{3}) (?P<body_bytes_sent>\d+) "(?P<http_referer>[^"]*)" "(?P<http_user_agent>[^"]*)"#,
445	            &[
446	                "remote_addr",
447	                "remote_user",
448	                "time_local",
449	                "method",
450	                "request_uri",
451	                "http_version",
452	                "status",
453	                "body_bytes_sent",
454	                "http_referer",
455	                "http_user_agent",
456	            ],
457	        ),
458	        "SYSLOG" => (
459	            r#"^(?P<syslog_timestamp>\w{3}\s+\d{1,2}\s+\d{2}:\d{2}:\d{2}) (?P<hostname>\S+) (?P<program>[^\[:]+)(?:\[(?P<pid>\d+)\])?: (?P<message>.+)$"#,
460	            &["syslog_timestamp", "hostname", "program", "pid", "message"],
461	        ),
462	        "POSTGRESQL" => (
463	            r#"^(?P<log_time>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\.\d+ \w+) \[(?P<pid>\d+)\] (?P<user_name>\S+)@(?P<database_name>\S+) (?P<severity>\w+):  (?P<message>.+)$"#,
464	            &[
465	                "log_time",
466	                "pid",
467	                "user_name",
468	                "database_name",
469	                "severity",
470	                "message",
471	            ],
472	        ),
473	        // "GENERIC" (and, defensively, anything that slipped past
474	        // `build_plugin`'s allow-list): capture everything as `message`.
475	        _ => (r#"^(?P<message>.+)$"#, &["message"]),
476	    }
477	}
