876	// ─────────────────────────────────────────────────────────────────────────────
877	// AppendPlugin
878	// ─────────────────────────────────────────────────────────────────────────────
879	
880	/// Append a value to a field, creating or widening a list as needed.
881	///
882	/// Elasticsearch's `append` semantics, which is what this exists for: the field
883	/// becomes a list if it is not one already, a list `value` extends rather than
884	/// nests, and a missing field is created as a single-element list
885	/// (`IngestDocument.appendFieldValue`, read for semantics only).
886	///
887	/// Issue #204: `append` used to be *mapped onto `set`* in the ES→xerj processor
888	/// translation (`es_compat.rs`), so `{"append": {"field": "tags", "value":
889	/// "b"}}` REPLACED `["a"]` with `"b"` instead of producing `["a", "b"]` —
890	/// under a `200 {"acknowledged": true}`, and disagreeing with the `_simulate`
891	/// interpreter, which has always implemented a real append. Two behaviours for
892	/// one pipeline; this is the one that runs at ingest.
893	pub struct AppendPlugin {
894	    field: String,
895	    value: Value,
896	}
897	
898	impl AppendPlugin {
899	    pub fn new(field: impl Into<String>, value: Value) -> Self {
900	        Self {
901	            field: field.into(),
902	            value,
903	        }
904	    }
905	}
906	
907	impl TransformPlugin for AppendPlugin {
908	    fn name(&self) -> &str {
909	        "append"
910	    }
911	
912	    fn process(&self, doc: &mut Value) -> ProcessAction {
913	        let Some(obj) = doc.as_object_mut() else {
914	            return ProcessAction::Pass;
915	        };
916	        let slot = obj
917	            .entry(self.field.clone())
918	            .or_insert_with(|| Value::Array(Vec::new()));
919	        match slot {
920	            Value::Array(existing) => match self.value.clone() {
921	                Value::Array(more) => existing.extend(more),
922	                one => existing.push(one),
923	            },
924	            scalar => {
925	                let previous = scalar.clone();
926	                let mut out = vec![previous];
927	                match self.value.clone() {
928	                    Value::Array(more) => out.extend(more),
929	                    one => out.push(one),
930	                }
931	                *scalar = Value::Array(out);
932	            }
933	        }
934	        ProcessAction::Pass
935	    }
936	}
