960	// UrlDecodePlugin
961	// ─────────────────────────────────────────────────────────────────────────────
962	
963	/// URL-decode (percent-decode) the string value of a field.
964	///
965	/// `+` is decoded as a space.  If the field is missing, not a string, or
966	/// decoding fails the document passes through unchanged.
967	pub struct UrlDecodePlugin {
968	    field: String,
969	}
970	
971	impl UrlDecodePlugin {
972	    pub fn new(field: impl Into<String>) -> Self {
973	        Self {
974	            field: field.into(),
975	        }
976	    }
977	
978	    fn percent_decode(s: &str) -> Option<String> {
979	        let mut out = Vec::with_capacity(s.len());
980	        let bytes = s.as_bytes();
981	        let mut i = 0;
982	        while i < bytes.len() {
983	            if bytes[i] == b'+' {
984	                out.push(b' ');
985	                i += 1;
986	            } else if bytes[i] == b'%' && i + 2 < bytes.len() {
987	                let hi = (bytes[i + 1] as char).to_digit(16)? as u8;
988	                let lo = (bytes[i + 2] as char).to_digit(16)? as u8;
989	                out.push(hi << 4 | lo);
990	                i += 3;
991	            } else {
992	                out.push(bytes[i]);
993	                i += 1;
994	            }
995	        }
996	        String::from_utf8(out).ok()
997	    }
998	}
999	
1000	impl TransformPlugin for UrlDecodePlugin {
1001	    fn name(&self) -> &str {
1002	        "url_decode"
1003	    }
1004	
1005	    fn process(&self, doc: &mut Value) -> ProcessAction {
1006	        if let Some(Value::String(s)) = doc.get_mut(&self.field) {
1007	            if let Some(decoded) = Self::percent_decode(s) {
1008	                *s = decoded;
1009	            }
1010	        }
1011	        ProcessAction::Pass
1012	    }
1013	}
