/// Inverse of [`map_proc_name`]: xerj stage type → ES processor name.
fn es_proc_name(xerj_type: &str) -> &str {
    match xerj_type {
        "drop_field" => "remove",
        "field_rename" => "rename",
        "timestamp_parse" => "date",
        "json_parse" => "json",
        "copy_field" => "copy",
        other => other,
    }
}

